      override def walk(y: Any): Any = y match {
        case t:TraitSelfType => t.getNamed
        case t:ObjectExprType => NF.makeMaybeIntersectionType(t.getExtended)
        case _ => super.walk(y)
      }
    }
    remover(x).asInstanceOf[Type]
  }


